Q: How to use Javascript to read local text file and read line by line? A: <p>Files can be processed line by line like this:</p>
<pre class="lang-js prettyprint-override"><code>async function * linesFromFile (file)
{
  let textStream = file.stream ().pipeThrough (
    new TextDecoderStream ('utf-8', { fatal: true }));

  let regex = /\r\n?|\n/g;
  let skipN = false, remainder = '';

  for await (let text of textStream)
  {
    if (skipN)
    {
      if (text.startsWith ('\n'))
        text = text.slice (1);
      skipN = false;
    }

    text = remainder + text;
    let li = 0;

    regex.lastIndex = remainder.length;
    for (let m; m = regex.exec (text);)
    {
      yield text.slice (li, m.index);
      li = regex.lastIndex;
    }

    remainder = text.slice (li);

    // if this chunk ends with '\r',
    // skips '\n' in the next text chunk beginning
    if (!remainder &amp;&amp; text.endsWith ('\r'))
      skipN = true;
  }

  yield remainder;
}
</code></pre>
<p>Usage:</p>
<pre class="lang-js prettyprint-override"><code>for await (let line of linesFromFile (file))
  console.log (line);
</code></pre>

Q: How to get a specific row by worksheet and rowindex in excel file A: <p>When you create a row, you have to set the Row index value for each row you added to the excel.</p>

<pre><code>Row headerRow = new Row() { RowIndex = new UInt32Value(1) }; //Here I used as 1(one), use accordingly
</code></pre>

<p>When you create a cell, you have to set the CellReference value for each cell you created.</p>

<pre><code>  Cell cell = new Cell() { };
  cell.CellReference = new StringValue("A1");
  cell.DataType = CellValues.String;
  cell.CellValue = new CellValue("Test value");
</code></pre>

<p>If the Row index and  cell reference is not set, the values will be null when you query among it.</p>

<p>Some other useful methods for using in excel</p>

<pre><code> //To get the CellReference
 private static string GetExcelCellReference(uint columnNumber, uint rowNumber)
    {
        return $"{GetExcelColumnName(columnNumber)}{rowNumber}";
    }

    //To get the excel column name using column number
    private static string GetExcelColumnName(uint columnNumber)
    {
        int dividend = (int)columnNumber;
        string columnName = String.Empty;
        int modulo;

        while (dividend &gt; 0)
        {
            modulo = (dividend - 1) % 26;
            columnName = Convert.ToChar(65 + modulo).ToString() + columnName;
            dividend = (int)((dividend - modulo) / 26);
        }

        return columnName;
    }

    //To get the excel column name from cellname or cellreference number
    private static string GetColumnName(string cellName)
    {
        // Create a regular expression to match the column name portion of the cell name.
        Regex regex = new Regex("[A-Za-z]+");
        Match match = regex.Match(cellName);

        return match.Value;
    }

    //To get the row index from cell name or cell reference number
    private static uint GetRowIndex(string cellName)
    {
        // Create a regular expression to match the row index portion the cell name.
        Regex regex = new Regex(@"\d+");
        Match match = regex.Match(cellName);

        return uint.Parse(match.Value);
    }
</code></pre>
